    for lam in lams:
        pred=np.zeros(N,int)
        for f in range(5):
            tr=folds!=f; te=~tr
            mu=X[tr].mean(0); sd=(X[tr].std(0)+1e-6) if std else np.ones(X.shape[1])
            Xt=(X[tr]-mu)/sd; Xe=(X[te]-mu)/sd
            # dual form for speed when d>n
            if Xt.shape[1]>Xt.shape[0]:
                K=Xt@Xt.T; a=np.linalg.solve(K+lam*np.eye(len(K)), Y[tr]-Y[tr].mean(0)); S=Xe@(Xt.T@a)
